examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchResponsiveDialog(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
        actions = {
            MonarchButton(text = {{cancel}}, onClick = { open = false })
            MonarchButton(text = {{confirm}}, onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        MonarchTextField(value = email, onValueChange = { email = it }, label = {{field}}, placeholder = {{placeholder}})
    }
}

examples.code:
MonarchButton(text = "Invite people", onClick = { open = true })
if (open) {
    MonarchResponsiveDialog(
        onDismissRequest = { open = false },
        title = "Invite people",
        description = "They get an email with a link to join.",
        actions = {
            MonarchButton(text = "Cancel", onClick = { open = false })
            MonarchButton(text = "Send invite", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        MonarchTextField(value = email, onValueChange = { email = it }, label = "Email address", placeholder = "name@example.com")
    }
}

if (open) {
    MonarchResponsiveDialog(
        onDismissRequest = { open = false },
        title = "Choose a workspace",
        sheetBelow = MonarchResponsiveDialogBreakpoint.Expanded,
        dismissible = false,
        actions = {
            MonarchButton(text = "Continue", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        },
    ) {
        MonarchText(text = "You belong to two workspaces. Choose the one to open.")
    }
}
